import re
from .exceptions import AwaitedMessagesShouldNotEmpty


class MessageVerification(object):

    def __init__(self):
        self._all_verified_messages = []
        self._awaited_messages_verified_result = []

    def add_awaited_messages(self, awaited_messages):
        if not awaited_messages:
            raise AwaitedMessagesShouldNotEmpty(awaited_messages)

        self._awaited_messages_verified_result = [[msg, False] for msg in awaited_messages]

        self._all_verified_messages = []

    def verify_messages(self, messages):
        self._all_verified_messages.extend(messages)

        for awaited_message_index, awaited_message_verify in enumerate(self._awaited_messages_verified_result):
            awaited_message, verify_result = awaited_message_verify
            if verify_result:
                continue

            awaited_message_verified_index = [index for index, message in enumerate(messages)
                                              if re.search(awaited_message, message)]

            if awaited_message_verified_index:
                self._awaited_messages_verified_result[awaited_message_index][1] = True
                messages = messages[awaited_message_verified_index[0] + 1:]

    def get_verify_result(self):
        return self._awaited_messages_verified_result

    def get_all_verified_messages(self):
        return self._all_verified_messages
